from __future__ import annotations

from collections import deque

from deepface_security_framework.config.schema import EmotionConfig


class EmotionAnalyzer:
    def __init__(self, config: EmotionConfig) -> None:
        self.config = config
        self.history: deque[dict[str, float]] = deque(maxlen=max(1, config.smoothing_window))

    def analyze(self, frame) -> dict:
        try:
            from deepface import DeepFace
        except ModuleNotFoundError as exc:
            raise RuntimeError(
                "DeepFace is not installed in this environment. Activate .venv and run: "
                "python -m pip install -r requirements.txt"
            ) from exc

        result = DeepFace.analyze(frame, actions=["emotion"], enforce_detection=False, silent=True)
        if isinstance(result, list):
            result = result[0]

        scores = result.get("emotion", {})
        normalized = {k: float(v) / 100.0 for k, v in scores.items()}
        self.history.append(normalized)

        smooth_scores = self._smooth_scores()
        dominant = max(smooth_scores, key=smooth_scores.get) if smooth_scores else None
        return {
            "dominant_emotion": dominant,
            "scores": smooth_scores,
            "raw_scores": normalized,
            "region": result.get("region"),
        }

    def _smooth_scores(self) -> dict[str, float]:
        if not self.history:
            return {}
        keys = set().union(*self.history)
        combined: dict[str, float] = {}
        for key in keys:
            combined[key] = sum(frame.get(key, 0.0) for frame in self.history) / len(self.history)
        return combined

from __future__ import annotations

from dataclasses import dataclass

from deepface_security_framework.config.schema import EmotionConfig


@dataclass
class EmotionDecision:
    passed: bool
    score: float
    top_blocked_emotion: str | None
    details: dict[str, float]


def evaluate_emotion_policy(scores: dict[str, float], config: EmotionConfig) -> EmotionDecision:
    weighted: dict[str, float] = {}
    for emotion in config.blocked_emotions:
        confidence = scores.get(emotion, 0.0)
        weight = config.weights.get(emotion, 1.0)
        weighted[emotion] = confidence * weight

    if not weighted:
        return EmotionDecision(True, 0.0, None, {})

    top_emotion = max(weighted, key=weighted.get)
    top_score = weighted[top_emotion]
    passed = top_score < config.threshold
    return EmotionDecision(passed, top_score, top_emotion, weighted)

from __future__ import annotations

from pathlib import Path

import cv2
import numpy as np

from deepface_security_framework.config.schema import IdentityConfig

SUPPORTED_IMAGE_EXTENSIONS = {".jpg", ".jpeg", ".png", ".webp", ".bmp"}


def _write_temp_frame(frame) -> Path:
    temp_dir = Path(".dfs_tmp")
    temp_dir.mkdir(parents=True, exist_ok=True)
    tmp_path = temp_dir / "live_frame.jpg"
    cv2.imwrite(str(tmp_path), frame)
    return tmp_path


def _load_image_any_path(path: Path):
    # Standard OpenCV path read first.
    image = cv2.imread(str(path))
    if image is not None:
        return image
    # Fallback for Windows/Unicode path handling.
    try:
        data = np.fromfile(str(path), dtype=np.uint8)
        if data.size == 0:
            return None
        return cv2.imdecode(data, cv2.IMREAD_COLOR)
    except Exception:
        return None


def _iter_image_files(directory: Path):
    for image_path in directory.rglob("*"):
        if image_path.is_file() and image_path.suffix.lower() in SUPPORTED_IMAGE_EXTENSIONS:
            yield image_path


def verify_reference(frame, config: IdentityConfig) -> tuple[bool, dict]:
    try:
        from deepface import DeepFace
    except ModuleNotFoundError as exc:
        raise RuntimeError(
            "DeepFace is not installed in this environment. Activate .venv and run: "
            "python -m pip install -r requirements.txt"
        ) from exc

    if not config.reference_image_path:
        return False, {"reason": "missing_reference_image"}
    if Path(config.reference_image_path).suffix.lower() not in SUPPORTED_IMAGE_EXTENSIONS:
        return False, {"reason": "invalid_reference_image_format"}

    reference_path = Path(config.reference_image_path)
    reference_img = _load_image_any_path(reference_path)
    if reference_img is None:
        return False, {"reason": "reference_image_unreadable"}

    result = DeepFace.verify(
        img1_path=frame,
        img2_path=reference_img,
        model_name=config.model_name,
        detector_backend=config.detector_backend,
        enforce_detection=False,
    )
    distance = float(result.get("distance", 1.0))
    threshold = float(config.distance_threshold)
    verified = distance <= threshold
    return verified, {"distance": distance, "threshold": threshold, "source": "reference"}


def verify_admin_pool(frame, config: IdentityConfig) -> tuple[bool, dict]:
    try:
        from deepface import DeepFace
    except ModuleNotFoundError as exc:
        raise RuntimeError(
            "DeepFace is not installed in this environment. Activate .venv and run: "
            "python -m pip install -r requirements.txt"
        ) from exc

    if not config.admin_faces_dir:
        return False, {"reason": "missing_admin_pool"}

    admin_dir = Path(config.admin_faces_dir)
    if not admin_dir.exists():
        return False, {"reason": "admin_pool_not_found"}
    if not admin_dir.is_dir():
        return False, {"reason": "admin_pool_not_directory"}

    matches: list[dict] = []
    for image_path in _iter_image_files(admin_dir):
        admin_img = _load_image_any_path(image_path)
        if admin_img is None:
            continue
        result = DeepFace.verify(
            img1_path=frame,
            img2_path=admin_img,
            model_name=config.model_name,
            detector_backend=config.detector_backend,
            enforce_detection=False,
        )
        distance = float(result.get("distance", 1.0))
        threshold = float(config.distance_threshold)
        if distance <= threshold:
            matches.append(
                {
                    "path": str(image_path),
                    "distance": distance,
                    "threshold": threshold,
                }
            )

    if matches:
        best = sorted(matches, key=lambda x: x["distance"])[0]
        return True, {"source": "admin_pool", "match": best}

    return False, {"reason": "no_admin_match", "source": "admin_pool"}


def verify_identity(frame, config: IdentityConfig) -> tuple[bool, dict]:
    if config.reference_image_path:
        matched, details = verify_reference(frame, config)
        if matched:
            return True, details
        details = dict(details)
        details["reason"] = details.get("reason", "reference_no_match")
        return False, details

    if config.admin_faces_dir:
        return verify_admin_pool(frame, config)

    return False, {"reason": "no_identity_sources_configured"}

from __future__ import annotations

import cv2
import numpy as np


class CameraStream:
    def __init__(self, camera_index: int = 0) -> None:
        self.camera_index = camera_index
        self.capture: cv2.VideoCapture | None = None

    def open(self) -> None:
        self.capture = cv2.VideoCapture(self.camera_index)
        if not self.capture.isOpened():
            raise RuntimeError("Unable to access camera.")

    def read(self) -> np.ndarray:
        if self.capture is None:
            raise RuntimeError("Camera is not open.")
        ok, frame = self.capture.read()
        if not ok:
            raise RuntimeError("Failed to read camera frame.")
        return frame

    def close(self) -> None:
        if self.capture is not None:
            self.capture.release()
            self.capture = None

from __future__ import annotations


def identity_reason(identity_ok: bool, details: dict) -> str:
    if identity_ok:
        return "Identity verification passed."
    reason = details.get("reason", "identity_verification_failed")
    if reason == "no_admin_match":
        return "Access denied: requesting user did not match any admin face."
    if reason == "missing_reference_image":
        return "Access denied: reference image is not configured."
    if reason == "invalid_reference_image_format":
        return "Access denied: reference image format is unsupported."
    if reason == "reference_image_unreadable":
        return "Access denied: reference image file could not be read."
    if reason == "reference_no_match":
        distance = details.get("distance")
        threshold = details.get("threshold")
        if distance is not None and threshold is not None:
            return (
                "Access denied: live face did not match reference image "
                f"(distance={float(distance):.4f}, threshold={float(threshold):.4f})."
            )
        return "Access denied: live face did not match reference image."
    if reason == "identity_consensus_failed":
        matches = details.get("matches")
        required = details.get("required")
        return (
            "Access denied: identity consensus failed across multiple frames "
            f"(matches={matches}, required={required})."
        )
    if reason == "admin_pool_not_found":
        return "Access denied: admin face pool path does not exist."
    if reason == "admin_pool_not_directory":
        return "Access denied: admin face pool path is not a directory."
    return f"Access denied: identity verification failed ({reason})."


def emotion_reason(emotion_ok: bool, top_emotion: str | None, score: float, threshold: float) -> str:
    if emotion_ok:
        return "Emotion policy passed."
    if top_emotion:
        return (
            f"Access denied: elevated risk emotion '{top_emotion}' detected "
            f"(score={score:.2f}, threshold={threshold:.2f}). "
            "Please normalize emotional state and retry."
        )
    return "Access denied: emotion policy failed."
